const res = await fetch('{{WA_API_BASE}}/api/v1/contacts', {
  method: 'POST',
  headers: {
    'Authorization': 'Bearer ' + process.env.SM_API_KEY, // sm_live_your_api_key
    'Content-Type': 'application/json',
    'Idempotency-Key': 'contact-sync-A-1042',
  },
  body: JSON.stringify({
    phone: '+919812345678',
    name: 'Asha Verma',
    email: 'asha@example.com',
    tags: { add: ['website-order'] },
    attributes: { city: 'Pune', lastOrderId: 'A-1042' },
  }),
});

// 201 = created, 200 = updated (upsert by phone)
const { data } = await res.json();
console.log(data.created, data.contact.id);
